// Writes timezones_gen.go: every time zone name of Go's tzdata that Node's Intl accepts, keyed by its lowercase
// spelling, so the Go server accepts time zone names as case-insensitively as ICU does.
// Usage: unzip -Z1 "$(go env GOROOT)/lib/time/zoneinfo.zip" | node go/server/testdata/gen-timezones.mjs > go/server/timezones_gen.go
import { readFileSync } from 'node:fs';
const names = readFileSync(0, 'utf8').split(/\r?\n/).filter((name) => name && !name.endsWith('/'));
const accepted = [];
for (const name of names.sort()) {
  try {
    new Intl.DateTimeFormat('en-US', { timeZone: name });
    accepted.push(name);
  } catch {}
}
const lines = accepted.map((name) => `\t${JSON.stringify(name.toLowerCase())}: ${JSON.stringify(name)},`);
process.stdout.write(`// Code generated by testdata/gen-timezones.mjs (Node ${process.version}, ICU ${process.versions.icu}); DO NOT EDIT.

package server

// timeZoneNames maps the lowercase spelling of every IANA time zone name Go's tzdata holds and Intl accepts to the
// name time.LoadLocation loads.
var timeZoneNames = map[string]string{
${lines.join('\n')}
}
`);
